import{_ as t,C as i,c as r,o as d,j as e,a8 as c,a as o,G as s}from"./chunks/framework.DBQiK-q5.js";const _=JSON.parse('{"title":"扩展包与商店","description":"","frontmatter":{"lang":"zh-cn","title":"扩展包与商店"},"headers":[],"relativePath":"config/package.md","filePath":"config/package.md","lastUpdated":1785395747000}'),n={name:"config/package.md"},p={id:"扩展包与商店",tabindex:"-1"};function h(u,a,g,k,f,b){const l=i("Badge");return d(),r("div",null,[e("h1",p,[a[0]||(a[0]=o("扩展包与商店 ",-1)),s(l,{type:"tip",text:"v1.6.0"}),a[1]||(a[1]=o()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#扩展包与商店","aria-label":'Permalink to "扩展包与商店 <Badge type="tip" text="v1.6.0" />"'},"​",-1))]),a[3]||(a[3]=c('<p>扩展包是以 <code>.sealpack</code> 为后缀的安装包，可以同时携带 JavaScript 脚本、牌堆、自定义回复、帮助文档和规则模板。包内的 <code>info.toml</code> 声明名称、版本、海豹版本要求、依赖、权限和内容清单。</p><div class="warning custom-block"><p class="custom-block-title">扩展包会执行第三方内容</p><p>扩展包可能发送网络请求、读写文件、启动 HTTP 服务，声明“危险操作”权限的包还可能执行外部程序。安装前应确认作者和来源，并在预览中检查权限、依赖和文件列表。</p><p>商店展示和权限声明不能代替代码审查。不要在生产骰子上安装来历不明的 <code>.sealpack</code> 文件。</p></div><h2 id="打开扩展包管理" tabindex="-1">打开扩展包管理 <a class="header-anchor" href="#打开扩展包管理" aria-label="Permalink to &quot;打开扩展包管理&quot;">​</a></h2><p>在 WebUI 中进入「扩展功能 - 扩展包」。页面包含“已安装包”和“商店”，并提供上传安装、URL 安装和重载入口。</p><p>已安装包有以下状态：</p><ul><li><strong>已安装</strong>：文件已保存，但内容尚未启用。</li><li><strong>已启用</strong>：包被允许参与下一次对应内容的加载。</li><li><strong>已禁用</strong>：包内容不再加载，临时缓存会被清理。</li><li><strong>错误</strong>：清单、依赖、版本或加载过程存在错误，应先查看详情和核心日志。</li></ul><p>“安装”和“启用”是两个步骤。启用或禁用后，页面会显示待重载内容；完成重载后变更才会完整应用。</p><h2 id="安装扩展包" tabindex="-1">安装扩展包 <a class="header-anchor" href="#安装扩展包" aria-label="Permalink to &quot;安装扩展包&quot;">​</a></h2><h3 id="从商店安装" tabindex="-1">从商店安装 <a class="header-anchor" href="#从商店安装" aria-label="Permalink to &quot;从商店安装&quot;">​</a></h3><p>在“商店”中打开扩展包详情，先检查版本、作者、说明、依赖、权限和文件。点击安装后仍会显示安装预览；确认内容无误后，可以选择“安装后启用”和“安装并启用后自动重载”。</p><p>“从清单安装”可以一次处理多个精确版本的扩展包，并逐项显示安装、启用和失败状态。批量安装前仍应逐个核对来源和权限。</p><h3 id="上传-sealpack" tabindex="-1">上传 <code>.sealpack</code> <a class="header-anchor" href="#上传-sealpack" aria-label="Permalink to &quot;上传 `.sealpack`&quot;">​</a></h3><p>在“上传安装”中选择本地 <code>.sealpack</code> 文件。海豹会先解析清单并展示将安装的文件、版本变化、权限和选项，确认后才执行安装。</p><h3 id="从-url-安装" tabindex="-1">从 URL 安装 <a class="header-anchor" href="#从-url-安装" aria-label="Permalink to &quot;从 URL 安装&quot;">​</a></h3><p>在“URL 安装”中填写直接指向 <code>.sealpack</code> 文件的地址。远程内容可能随时变化，应只使用可信作者提供的固定版本地址，并仔细核对安装预览。</p><p>海豹会检查包格式、路径、版本约束和商店提供的哈希信息。检查通过只表示文件结构符合要求，不代表其中的脚本逻辑可信。</p><h2 id="依赖与版本" tabindex="-1">依赖与版本 <a class="header-anchor" href="#依赖与版本" aria-label="Permalink to &quot;依赖与版本&quot;">​</a></h2><p>扩展包可以声明：</p><ul><li>适用的最低和最高海豹版本；</li><li>依赖的其他扩展包 ID；</li><li>依赖包需要满足的语义化版本范围。</li></ul><p>依赖缺失或版本不符时，扩展包不能正常启用。商店或清单安装可以按依赖关系批量处理；手工上传时，应根据预览提示先安装正确版本的依赖。禁用或卸载被其他包依赖的扩展包前，也要检查受影响的包。</p><h2 id="启用、禁用与重载" tabindex="-1">启用、禁用与重载 <a class="header-anchor" href="#启用、禁用与重载" aria-label="Permalink to &quot;启用、禁用与重载&quot;">​</a></h2><p>在“已安装包”中可以启用或禁用单个包。状态变化后，点击页面顶部“重载扩展”，或从下拉菜单只重载指定内容：</p><ul><li>脚本；</li><li>牌堆；</li><li>自定义回复；</li><li>帮助文档；</li><li>规则模板。</li></ul><p>只改动一种内容时，按类型重载可以减少等待时间。帮助文档和大量 JavaScript 插件的重载可能较慢；重载期间不要连续重复点击，也不要重启核心。</p><p>禁用包会清理运行缓存，但不会删除 <code>.sealpack</code> 源文件和用户数据。重新启用并重载后，内容会从包中重建。</p><h2 id="卸载与用户数据" tabindex="-1">卸载与用户数据 <a class="header-anchor" href="#卸载与用户数据" aria-label="Permalink to &quot;卸载与用户数据&quot;">​</a></h2><p>卸载时可以选择：</p><ul><li><code>full - 完全卸载</code>：删除包文件、运行缓存、配置和用户数据。</li><li><code>keep_data - 保留数据</code>：删除包文件和运行缓存，保留用户配置及运行数据，便于以后重新安装同一包。</li></ul><p>扩展包的用户数据位于 <code>data/extensions/&lt;作者&gt;/&lt;包名&gt;/_userdata/</code>，其中可能包括 <code>config.json</code> 和插件自行保存的数据。重要数据应在卸载前备份；“完全卸载”不可通过 WebUI 撤销。</p><p>上传或商店安装的源包通常保存在 <code>data/packages/</code>，解压后的运行缓存位于 <code>cache/packages/</code>。如果源 <code>.sealpack</code> 丢失，页面会显示“仅缓存安装”；应放回源文件并刷新，而不是长期依赖缓存。</p><h2 id="权限说明" tabindex="-1">权限说明 <a class="header-anchor" href="#权限说明" aria-label="Permalink to &quot;权限说明&quot;">​</a></h2><p>安装预览会显示包在 <code>info.toml</code> 中声明的权限：</p><ul><li><strong>网络</strong>：允许发起 HTTP 请求；包可以进一步声明允许访问的域名白名单。</li><li><strong>文件读取</strong>：允许读取声明路径内的文件。未声明的读取请求会被包沙箱拒绝。</li><li><strong>文件写入</strong>：允许写入声明路径；未额外声明时默认只允许写入包自己的 <code>_userdata</code> 目录。</li><li><strong>危险操作</strong>：允许执行外部程序等高风险行为。只应授予经过代码审查的扩展包。</li><li><strong>HTTP 服务</strong>：允许扩展包监听 HTTP 服务。启用前应检查监听地址、端口、防火墙和反向代理配置。</li><li><strong>扩展间通信</strong>：允许与清单列出的其他扩展包通信。</li></ul><p>权限声明用于限制包通过扩展包接口发起的操作，但不是完整的恶意代码防护边界。涉及“危险操作”、广泛文件权限或不受限网络访问时，应在隔离环境中先行验证。</p><h2 id="与其他扩展功能的关系" tabindex="-1">与其他扩展功能的关系 <a class="header-anchor" href="#与其他扩展功能的关系" aria-label="Permalink to &quot;与其他扩展功能的关系&quot;">​</a></h2><p>扩展包是内容的分发和生命周期管理层：</p><ul><li>包内脚本加载后成为 JavaScript 扩展，并通过 <code>.ext</code> 管理群内启用状态。</li><li>包内牌堆由 <code>.draw</code> 和文案中的 <code>#{DRAW-牌组名}</code> 使用。</li><li>包内自定义回复与本地回复共同参与匹配；包被禁用后，相关回复在重载后停止生效。</li><li>包内帮助文档进入 <code>.help</code> 和 <code>.find</code> 的搜索索引。</li><li>包内规则模板可以注册游戏系统、属性别名、默认骰面和群名片模板，并可由 <code>.set &lt;规则名&gt;</code> 选用。</li></ul><p>手工上传的本地文件仍在各自的牌堆、回复、帮助文档和 JS 页面管理。由扩展包提供的内容应优先通过扩展包页面升级、禁用或卸载，避免直接修改缓存文件；缓存会在重载或升级时重建。</p>',38))])}const q=t(n,[["render",h]]);export{_ as __pageData,q as default};
